INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Programmiertool immer einen Debugger hat?', 2, '[{"text": "Ja", "correct": true, "because": "Typisches Feature"}, {"text": "Nein", "correct": false, "because": "Standard in den meisten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature hilft mir, Code schneller zu schreiben?', 3, '[{"text": "Autovervollständigung", "correct": true, "because": "Vervollständigt Befehle"}, {"text": "Syntaxhervorhebung", "correct": false, "because": "Nur Lesbarkeit"}, {"text": "Dateiexplorer", "correct": false, "because": "Nur Navigation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet ein Entwicklungsprogramm?', 5, '[{"text": "Code-Editor", "correct": true, "because": "Zum Schreiben"}, {"text": "Debugger", "correct": true, "because": "Fehler finden"}, {"text": "Versionierung", "correct": true, "because": "Verfolgt Änderungen"}, {"text": "Grafikdesign", "correct": false, "because": "Andere Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es unterstützt mehrere Sprachen. b) Es ist immer kostenpflichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kostenlose Optionen existieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Tool für die Programmierung nutze?', 4, '[{"text": "Syntaxhervorhebung", "correct": false, "because": "Verbessert Lesbarkeit"}, {"text": "Projektverwaltung", "correct": false, "because": "Organisiert Code"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Entwicklungsprogramm nur für Profis ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Anfänger"}, {"text": "Ja", "correct": false, "because": "Breit einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wähle ich, um Java-Code zu debuggen?', 3, '[{"text": "Eclipse", "correct": true, "because": "Starker Debugger"}, {"text": "Notepad", "correct": false, "because": "Nur Text"}, {"text": "Browser", "correct": false, "because": "Kein Entwicklungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Programmiertool?', 5, '[{"text": "Produktivität", "correct": true, "because": "Autovervollständigung"}, {"text": "Fehlererkennung", "correct": true, "because": "Debugging-Tools"}, {"text": "Code-Navigation", "correct": true, "because": "Übersicht erleichtert"}, {"text": "Grafikerstellung", "correct": false, "because": "Andere Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) es mehrere Sprachen unterstützt und b) es nur für Python ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um mit einem Entwicklungsprogramm zu programmieren?', 4, '[{"text": "Editor", "correct": false, "because": "Zum Schreiben nötig"}, {"text": "Debugger", "correct": false, "because": "Hilft bei Fehlern"}, {"text": "Grafiktablet", "correct": true, "because": "Kein Programmierfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Entwicklungsprogramm immer cloudbasiert?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal nutzbar"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen helfen bei der Fehlersuche?', 4, '[{"text": "Breakpoints", "correct": true, "because": "Stoppen Ausführung"}, {"text": "Variableninspektion", "correct": true, "because": "Zeigt Werte"}, {"text": "Farbauswahl", "correct": false, "because": "Kein Debug-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für große Projekte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Aufgaben"}, {"text": "Ja", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Entwicklungsprogramm?', 3, '[{"text": "Effiziente Codierung", "correct": true, "because": "Tools unterstützen"}, {"text": "Datenbankdesign", "correct": false, "because": "Andere Software"}, {"text": "Webgestaltung", "correct": false, "because": "Teilweise möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es bietet Syntaxhervorhebung. b) Es ersetzt Kommandozeilen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommandozeilen ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Projektverwaltung?', 4, '[{"text": "Code organisieren", "correct": true, "because": "Strukturiert Arbeit"}, {"text": "Grafik rendern", "correct": false, "because": "Andere Software"}, {"text": "Netzwerk prüfen", "correct": false, "because": "Kein Netzwerktool"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Entwicklungsprogramm immer kostenlos ist?', 2, '[{"text": "Nein", "correct": true, "because": "Manche kostenpflichtig"}, {"text": "Ja", "correct": false, "because": "Verschieden verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Programmiertool?', 5, '[{"text": "Schnelleres Codieren", "correct": true, "because": "Autovervollständigung"}, {"text": "Fehlererkennung", "correct": true, "because": "Debugging"}, {"text": "Projektübersicht", "correct": true, "because": "Verwaltung hilft"}, {"text": "Datenbankverwaltung", "correct": false, "because": "Andere Tools"}]'),
